      const mat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, depthWrite: false });
      const g = new THREE.Group(); const m = new THREE.Mesh(GEO.plane, mat); m.position.y = -0.18; g.add(m); g.rotation.x = -PITCH;
      this.standsG.add(g);
