        const neon = (draw, col) => { c.save(); c.shadowColor = col; c.shadowBlur = 30; c.strokeStyle = col; c.lineWidth = 10; draw('s'); c.shadowBlur = 14; draw('s'); c.restore(); c.save(); c.strokeStyle = '#fff6fb'; c.lineWidth = 3; draw('s'); c.restore(); };
