    if (word !== this.crowdWord) { this.crowdWord = word; this.$.crowdL.textContent = word; this.$.crowd.classList.toggle('up', m > 0.25); this.$.crowd.classList.toggle('down', m < -0.2); }
    this.$.crowdB.style.left = (50 + 46 * m).toFixed(1) + '%';
