      this.shafts.forEach((m, i) => { m.rotation.z = m.userData.r0 + Math.sin(t * 0.35 + i * 1.9) * 0.045; m.material.opacity = 0.085 + 0.05 * ex * (0.5 + up) + 0.015 * Math.sin(t * 0.8 + i); });
