      const yn = ed.querySelector('.fbg-yn'), yno = ed.querySelector('.fbg-yno'), msg = ed.querySelector('.fbg-ymsg');
      yn.addEventListener('input', () => { const v = cleanYouName(yn.value); d.label = v || 'YOU'; this.applyYou(); });
