    if (a) { a.name = d.label; a.num = d.num; a.look.skin = d.skin; a.drawKit(this.kit || kitFrom(DEFAULT_LOOK.colors)); const e = a.expr; a.expr = ''; a.setExpr(e || 'neutral'); }
